import {newRound,roles,choose,perform,place,remove,checkTrain,canAdvance} from './engine.js';
import {TRAIN_CARRIAGE_ART} from './train-art.js';
const app=document.querySelector('#app'),live=document.querySelector('#live');
const content=await fetch('content.json').then(r=>{if(!r.ok)throw Error('題庫未能載入');return r.json();});
const ready=await fetch('audio-ready.json').then(r=>r.json());
const audioFiles=new Set(ready.files);
const titles={life:'小島生活任務',train:'小島句子列車'};
let game=null,page='home',kind='life',muted=false,lastFrame=performance.now(),serial=0,audioTicket=0,audioPending=false,audioEnd=null,lastSpoken=null;
const speaker=new Audio();speaker.preload='auto';
const completed={life:new Set(),train:new Set()},seenDemo=new Set(),imageCache=new Map();
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8z"/>',reset:'<path d="M4 10a9 9 0 1 1 1 8M4 4v6h6"/>',sound:'<path d="M3 9h5l5-5v16l-5-5H3zM17 8q5 4 0 8M20 5q8 7 0 14"/>',mute:'<path d="M3 9h5l5-5v16l-5-5H3zM17 9l5 6m0-6-5 6"/>',arrow:'<path d="M3 12h18m-7-7 7 7-7 7"/>',check:'<path d="m4 12 6 6L21 4"/>',cross:'<path d="m6 6 12 12M18 6 6 18"/>',hand:'<path d="M9 13V4a2 2 0 0 1 4 0v7-3a2 2 0 0 1 4 0v4-2a2 2 0 0 1 4 0v6q0 6-6 6h-3q-3 0-5-3l-4-6q-1-3 2-2z"/>',book:'<path d="M12 5q-5-3-10-1v15q5-2 10 1 5-3 10-1V4q-5-2-10 1v15"/>',back:'<path d="M21 12H3m7-7-7 7 7 7"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;}
function sentence(s){return esc(s).replace(/只有/g,'<b class="only">只有</b>').replace(/才/g,'<b class="then">才</b>').replace(/【？】/g,'<span class="gap">？</span>').replace(/，/g,'<span class="punct">，</span>').replace(/。/g,'<span class="punct">。</span>');}
function atlas(src,cols,rows,index,label,cls=''){const x=index%cols,y=Math.floor(index/cols);return `<svg class="picture ${cls}" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(label)}"><svg x="0" y="0" width="100" height="100" viewBox="${x*100} ${y*100} 100 100" overflow="hidden"><image href="assets/${src}" width="${cols*100}" height="${rows*100}" preserveAspectRatio="none"/></svg></svg>`;}
// For scene sheets the cell is 4:3; image itself keeps its native aspect ratio.
function scenePic(q,frame=0,cls=''){return `<svg class="scene ${cls}" data-scene="${q.scene}" data-frame="${frame}" viewBox="0 0 400 300" role="img" aria-label="${esc(q.condition+'，'+q.result)}"><svg class="scene-window" viewBox="${frame%4*400} ${Math.floor(frame/4)*300} 400 300" x="0" y="0" width="400" height="300" overflow="hidden"><image href="assets/${q.scene}-16-v1.png" width="1600" height="1200" preserveAspectRatio="xMidYMid meet"/></svg></svg>`;}
function pairPic(q,panel=0,cls=''){return atlas(`${q.scene}-pair-v1.png`,2,1,panel,panel?q.result:q.condition,cls);}
const vocabIndex={'刷牙':0,'拍球':1,'洗手':2,'跳繩':3,'畫畫':4,'畫圖畫':4,'踢球':5,'踢足球':5,'梳頭':6,'掃地':7,'吃雪糕':8,'吃香蕉':9,'游泳':10,'吃西瓜':11,'洗臉':12,'吃餅乾':13};
function wordPicture(w){const p=w.picture;if(!p)return '';if(p.kind==='vocab')return atlas('vocab-v1.png',4,4,vocabIndex[p.key],w.text);if(p.kind==='person')return atlas('vocab-v1.png',4,4,14,w.text);if(p.kind==='relation')return `<span class="relation-picture" aria-hidden="true">${p.key==='只有'?'◇':'→'}</span>`;if(p.kind==='scene')return scenePic(content.life.find(q=>q.scene===p.scene),p.frame);if(p.kind==='train')return pairPic(content.train.find(q=>q.scene===p.scene),p.panel);return '';}
function wordFace(id,withPicture=true){const w=content.words[id];return `${withPicture?wordPicture(w):''}<strong class="word-text ${w.picture?'':'punct'}">${esc(w.text)}</strong>${w.jyutping?`<small class="jp">${w.jyutping}</small>`:''}`;}
function stopAudio(){audioTicket++;speaker.pause();speaker.removeAttribute('src');speaker.load();audioPending=false;audioEnd=null;$('.is-reading')?.classList.remove('is-reading');}
function say(id,done=null,{essential=false}={}){
  if(essential&&game?.speechDone)return;
  stopAudio();lastSpoken={id,done,essential};
  if(muted){done?.();return;}
  const file=content.audio[id]?.file;
  if(!file||!audioFiles.has(file)){if(essential)audioFailure();return;}
  const ticket=audioTicket,current=game;audioPending=true;let ended=false;
  const finish=()=>{if(ticket!==audioTicket||ended)return;ended=true;audioPending=false;audioEnd=null;if(done&&current===game){if(game?.paused)game.clock.after(0,done);else done();}};
  audioEnd=finish;speaker.onended=finish;speaker.onerror=()=>{if(ticket!==audioTicket)return;audioPending=false;if(essential)audioFailure();};
  speaker.src=file;document.querySelector(`[data-audio="${id}"]`)?.classList.add('is-reading');
  speaker.play().catch(()=>{if(ticket===audioTicket){audioPending=false;if(essential)audioFailure();}});
}
function audioFailure(){if(game){game.speechError=true;const el=$('#feedback');if(el)el.innerHTML='<span class="retry">讀音未能播放；可重播或關閉聲音。</span>';}}
function cancelDrags(){if(!game)return;for(const [pointer,d]of game.drags){d.ghost?.remove();if(app.hasPointerCapture(pointer))app.releasePointerCapture(pointer);}game.drags.clear();document.querySelectorAll('.dragging,.drop-target').forEach(el=>el.classList.remove('dragging','drop-target'));}
function dispose(){cancelDrags();if(game)game.clock.clear();game=null;stopAudio();lastSpoken=null;app.className='';}
function navigation(type){return `<nav class="question-nav" aria-label="題號">${content[type].map((q,i)=>`<button class="question-dot ${game?.index===i&&page==='play'?'current':''} ${completed[type].has(i)?'done':''} ${type==='train'?(i<3?'beginner':'advanced'):''}" data-jump="${i}" data-kind="${type}" aria-label="跳到第 ${i+1} 題" ${game?.index===i&&page==='play'?'aria-current="step"':''}>${i+1}</button>`).join('')}</nav>`;}
function toolbar(){const inGame=page==='play',inSection=page!=='home';return `<div class="toolbar"><button data-action="home" class="control" aria-label="返回主頁">${icon('home')}<span>主頁</span></button>${inSection?`<button data-action="review" class="control">${icon('book')}<span>重溫</span></button>`:''}${inGame?`<button data-action="pause" class="control pause-control" aria-pressed="${game.paused}">${icon(game.paused?'play':'pause')}<span>${game.paused?'繼續':'暫停'}</span></button><button data-action="restart" class="control">${icon('reset')}<span>重開</span></button>`:''}<button data-action="sound" class="control sound-control" aria-label="${muted?'開啟聲音':'關閉聲音'}" aria-pressed="${!muted}">${icon(muted?'mute':'sound')}<span>${muted?'靜音':'聲音'}</span></button></div>`;}
function header(){return `<header><a class="brand" href="#home" data-action="home"><span class="brand-icon">◇</span><span>小島中文<span class="brand-small">一起看圖・一起組句</span></span></a>${toolbar()}</header>`;}
function setRoute(hash){history.replaceState(null,'','#'+hash);document.title=(page==='home'?'只有……，才……。':titles[kind])+'｜小島中文';}
function home(){dispose();page='home';setRoute('home');render();}
function intro(type){dispose();kind=type;page='intro';setRoute('intro-'+type);render();}
function review(){const type=kind;dispose();kind=type;page='review';setRoute('review-'+type);render();}
function start(type=kind,index=0){dispose();kind=type;page='play';game=newRound(type,index,content);lastFrame=performance.now();setRoute(type);render();preloadQuestion(game.q);if(type==='life'){if(!seenDemo.has(game.q.mode)){seenDemo.add(game.q.mode);showDemo();}say(game.q.questionAudio);}}
function preloadQuestion(q){const urls=kind==='life'?[`assets/${q.scene}-16-v1.png`,'assets/vocab-v1.png']:[`assets/${q.scene}-pair-v1.png`,'assets/train-engine-16-v1.png','assets/train-carriages-16-v3.png','assets/vocab-v1.png'];for(const url of urls)if(!imageCache.has(url)){const img=new Image();img.src=url;imageCache.set(url,img);}}
function render(){app.className=game?.paused?'paused':'';app.innerHTML=`<main class="${page}-page">${header()}${page==='home'?homeMarkup():page==='intro'?introMarkup():page==='review'?reviewMarkup():kind==='life'?lifeMarkup():trainMarkup()}</main>`;}
function homeMarkup(){return `<section class="home-heading"><span class="eyebrow">看圖學句子 · 雙人合作</span><h1>……<b class="only">只有</b>……<span class="punct">，</span><br><b class="then">才</b>……<span class="punct">。</span></h1><p>和同學一起，發現小島生活中的小秘密。</p></section><section class="game-menu" aria-label="選擇遊戲"><button class="game-entry life-entry" data-intro="life"><div class="menu-picture">${scenePic(content.life[0],content.life[0].resultFrame)}</div><span class="entry-label"><span><small>01 · 看圖選詞</small><strong>小島生活任務</strong></span><span class="entry-arrow">${icon('arrow')}</span></span></button><button class="game-entry train-entry" data-intro="train"><div class="menu-picture train-cover">${engineArt(0)}</div><span class="entry-label"><span><small>02 · 合作組句</small><strong>小島句子列車</strong></span><span class="entry-arrow">${icon('arrow')}</span></span></button></section><p class="home-foot">兩位同學，一起完成。慢慢想，沒有時間限制。</p>`;}
function introMarkup(){const q=content[kind][0];return `<section class="section-title"><small>兩人一組・一起試一試</small><h1>${titles[kind]}</h1>${navigation(kind)}</section><section class="intro-layout"><div class="intro-art">${kind==='life'?scenePic(q,q.resultFrame):pairPic(q,1)}</div><div class="intro-copy"><h2>${kind==='life'?'一人選圖，一人做動作。':'把句子送上小火車。'}</h2><div class="intro-steps" aria-label="圖像玩法介紹">${kind==='life'?`<span class="mini-card">${scenePic(q,q.conditionFrame)}${icon('hand')}</span><span>→</span><span class="mini-gap">？</span><span>→</span><span class="mini-action">${icon('hand')}${icon('play')}</span>`:`<span class="mini-card">我</span><span>→</span><span class="mini-car">▱</span><span>→</span>${engineArt(0)}`}</div><p>${kind==='life'?'選好圖卡，再由另一位同學按下動作按鈕。每題交換角色。':'一起拖詞卡和標點上車，也可以點詞卡，再點車廂。'}</p>${kind==='train'?'<div class="tier-guide"><span class="beginner">★ 初階 1–3</span><span class="advanced">★★ 高階 4–5</span></div>':''}<button class="primary" data-action="start">${icon('play')}開始${kind==='life'?'任務':'組句'}</button><button class="secondary" data-action="review">${icon('book')}先看圖文重溫</button></div></section>`;}
function progress(){return `<div class="progress"><h1>${titles[kind]}<small>第 ${game.index+1} 題／${content[kind].length}</small></h1>${kind==='train'?`<span class="tier ${game.q.showLengthHints?'beginner':'advanced'}">${game.q.showLengthHints?'★ 初階':'★★ 高階'}</span>`:''}${navigation(kind)}</div>`;}
function lifeMarkup(){const g=game,q=g.q,answered=g.phase!=='choosing',r=roles(g.index),leftMissing=q.mode==='condition',blank=side=>!answered&&(side==='left'?leftMissing:!leftMissing);return `${progress()}<section class="life-board play-area"><div class="relation-board"><div class="relation-cell ${blank('left')?'empty-cell':''}" data-side="left">${blank('left')?'<span class="blank-symbol">？</span>':scenePic(q,q.conditionFrame)}${blank('left')?`<span class="pointing-hand" aria-hidden="true">${icon('hand')}</span>`:''}</div><span class="relation-arrow" aria-hidden="true">${icon('arrow')}</span><div class="relation-cell ${blank('right')?'empty-cell':''}" data-side="right">${blank('right')?'<span class="blank-symbol">？</span>':scenePic(q,q.resultFrame)}${blank('right')?`<span class="pointing-hand" aria-hidden="true">${icon('hand')}</span>`:''}</div><div class="demo-track" aria-hidden="true">${icon('hand')}</div></div><div class="life-copy"><p class="sentence">${sentence(answered?q.sentence:q.prompt)}</p><div class="feedback" id="feedback" role="status">${g.phase==='selected'?`${icon('check')}<span class="actor-hint">${person(r.actor)}${icon('hand')}${icon('play')}</span>`:g.wrong.length?`<span class="retry">${icon('cross')}再試一試！</span>`:''}</div><div class="read-controls"><button class="small-control" data-action="read" aria-label="重播題目或完整句子">${icon('sound')}</button><button class="small-control" data-action="demo" aria-label="重播無文字操作示範">${icon('hand')}</button></div></div></section><section class="life-bottom play-area"><div class="choices-station"><div class="role">${person(r.chooser)}${icon('hand')}</div><div class="life-options">${q.options.map(id=>`<button class="word-card ${g.selected===id?(answered?'correct':'wrong'):''}" data-option="${id}" ${answered?'disabled':''} aria-label="${esc(content.words[id].text)}">${wordFace(id)}${g.selected===id?`<span class="card-mark">${icon(answered?'check':'cross')}</span>`:''}</button>`).join('')}</div></div><div class="action-station"><div class="role">${person(r.actor)}${icon('play')}</div><button class="action-button ${g.phase==='selected'?'ready-action':''}" data-action="act" aria-label="同學 ${r.actor} 觸發動作" ${g.phase==='selected'?'':'disabled'}>${icon('hand')}${icon('play')}</button><div class="action-caption">一起來！</div></div></section>`;}
function person(n){return `<span class="person person-${n}" aria-label="同學 ${n}"><svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="11" r="7"/><path d="M7 36v-6a13 13 0 0 1 26 0v6z"/></svg><b>${n}</b></span>`;}
function engineArt(frame=0){return `<svg class="engine-art" data-engine data-frame="${frame}" viewBox="0 0 400 300" role="img" aria-label="彩繪蒸氣火車"><svg class="engine-window" x="0" y="0" width="400" height="300" viewBox="${frame%4*400} ${Math.floor(frame/4)*300} 400 300" overflow="hidden"><image href="assets/train-engine-16-v1.png" width="1600" height="1200"/></svg></svg>`;}
function carriage(frame=0){const f=TRAIN_CARRIAGE_ART.frames[frame], [x,y,r,b]=f.bounds,w=r-x,h=b-y;return `<svg class="car-art" viewBox="0 0 258 270" aria-hidden="true"><svg class="car-window" x="${(258-w)/2}" y="${270-h}" width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden"><image href="assets/train-carriages-16-v3.png" width="1086" height="1448"/></svg></svg>`;}
function bankOrder(q){const n=q.tokens.length;return Array.from({length:n},(_,i)=>q.tokens[(i*3+2)%n]);} // 7 and 8 are coprime to 3.
function trainBoard(){const g=game,q=g.q;return `<section class="train-track" aria-label="句子列車"><div class="rails"></div><div class="rake" id="rake"><div class="carriages">${q.tokens.map((expected,i)=>{const id=g.slots[i],w=id?content.words[id]:null;return `<button class="train-slot ${g.wrong.includes(i)?'wrong-slot':''} ${g.selected===id&&id?'selected-card':''}" data-slot="${i}" ${id?`data-token="${id}"`:''} aria-label="第 ${i+1} 節車廂${w?'：'+w.text:'，空位'}" ${g.phase!=='assembling'?'disabled':''}>${carriage()}<span class="car-content">${w?`<strong>${esc(w.text)}</strong>`:`<span class="slot-gap ${q.showLengthHints?'length-hint':''}" ${q.showLengthHints?`style="width:${Math.min(100,content.words[expected].text.length*17)}%"`:''}></span>`}</span>${g.wrong.includes(i)?`<span class="slot-error">${icon('cross')}</span>`:''}</button>`;}).join('')}</div>${engineArt()}</div></section><div class="feedback" id="feedback" role="status">${g.wrong.length?`<span class="retry">${icon('cross')}再試一試！</span>`:''}</div><section class="word-bank" id="word-bank" aria-label="詞庫，也可把詞卡放回這裏" style="--cards:${q.tokens.length}">${bankOrder(q).map(id=>`<button class="word-card train-word ${g.slots.includes(id)?'used':''} ${g.selected===id?'selected-card':''}" data-token="${id}" aria-label="詞卡：${esc(content.words[id].text)}" ${g.slots.includes(id)||g.phase!=='assembling'?'disabled':''}>${wordFace(id)}</button>`).join('')}</section>`;}
function trainMarkup(){const q=game.q;return `${progress()}<section class="train-story play-area"><div>${pairPic(q,0)}<span class="relation-arrow">${icon('arrow')}</span>${pairPic(q,1)}</div><div class="train-story-copy">${game.phase==='departing'?`<p class="sentence">${sentence(q.sentence)}</p>`:`<div class="cooperation">${person(1)}${icon('hand')}${person(2)}${icon('hand')}</div><p>看圖，把詞卡和標點送上車。</p><span class="relation-guide"><b class="only">只有</b>${icon('arrow')}<b class="then">才</b></span>`}<button class="small-control" data-action="read" aria-label="重播句子" ${game.phase==='departing'?'':'disabled'}>${icon('sound')}</button></div></section><div id="train-board" class="play-area">${trainBoard()}</div>`;}
function reviewMarkup(){return `<section class="section-title review-title"><small>看圖・讀一讀</small><h1>${titles[kind]}・句子重溫</h1><button class="primary" data-action="start">${icon('play')}重新遊玩</button></section><section class="review-grid">${content[kind].map((q,i)=>`<article class="review-card"><span class="review-number">${String(i+1).padStart(2,'0')}</span><div class="review-pictures">${kind==='life'?scenePic(q,q.conditionFrame):pairPic(q,0)}<span>${icon('arrow')}</span>${kind==='life'?scenePic(q,q.resultFrame):pairPic(q,1)}</div><p class="sentence">${sentence(q.sentence)}</p><button class="control" data-audio="${q.audio}" aria-label="朗讀：${q.sentence}">${icon('sound')}聽一聽</button></article>`).join('')}</section>`;}
function showDemo(){const g=game;if(!g||g.phase!=='choosing')return;g.demo=g.clock.position+2600;app.classList.add('show-demo');$('.relation-board')?.classList.toggle('demo-right',g.q.mode==='result');}
function updateTrain(){if(game?.type!=='train')return;const focus=document.activeElement;const selector=focus?.dataset.slot!==undefined?`[data-slot="${focus.dataset.slot}"]`:focus?.dataset.token?`[data-token="${focus.dataset.token}"]:not(:disabled)`:null;$('#train-board').innerHTML=trainBoard();for(const d of game.drags.values())document.querySelectorAll(`[data-token="${d.id}"]`).forEach(el=>el.classList.add('dragging'));if(selector)$(selector)?.focus({preventScroll:true});}
function later(g,delay,fn){g.clock.after(delay,()=>{if(game===g)fn();});}
function nextIfReady(g){if(game!==g||!canAdvance(g))return;g.advancing=true;completed[kind].add(g.index);later(g,400,()=>{if(g.index+1===content[kind].length)review();else start(kind,g.index+1);});}
function playAnswer(g){g.speechError=false;say(g.q.audio,()=>{if(game!==g)return;g.speechDone=true;nextIfReady(g);},{essential:true});}
function act(){const g=game;if(!g||!perform(g))return;stopAudio();app.classList.remove('show-demo');render();later(g,1200,()=>playAnswer(g));later(g,2800,()=>{g.animationDone=true;nextIfReady(g);});}
function check(){const g=game;if(!g)return;const v=checkTrain(g);if(!v)return;if(!v.correct){updateTrain();say(content.feedback['再試一試。']);return;}stopAudio();render();playAnswer(g);later(g,2800,()=>{g.animationDone=true;nextIfReady(g);});}
function togglePause(){const g=game;if(!g)return;cancelDrags();g.paused=!g.paused;g.clock.paused=g.paused;app.classList.toggle('paused',g.paused);if(g.paused)speaker.pause();else if(audioPending&&!muted)speaker.play().catch(()=>audioFailure());const b=$('.pause-control');b.innerHTML=icon(g.paused?'play':'pause')+`<span>${g.paused?'繼續':'暫停'}</span>`;b.setAttribute('aria-pressed',String(g.paused));if(kind==='train'&&g.phase==='assembling')updateTrain();lastFrame=performance.now();if(!g.paused)nextIfReady(g);}
function toggleSound(){muted=!muted;stopAudio();if(muted&&game&&['acting','departing'].includes(game.phase)){game.speechDone=true;nextIfReady(game);}const b=$('.sound-control');b.innerHTML=icon(muted?'mute':'sound')+`<span>${muted?'靜音':'聲音'}</span>`;b.setAttribute('aria-label',muted?'開啟聲音':'關閉聲音');b.setAttribute('aria-pressed',String(!muted));}
app.addEventListener('click',e=>{const b=e.target.closest('button,[data-action="home"]');if(!b||b.disabled||e.defaultPrevented)return;const a=b.dataset.action;if(a==='home'){e.preventDefault();home();return;}if(a==='pause'){togglePause();return;}if(a==='restart'){completed[kind].clear();start();return;}if(a==='review'){review();return;}if(a==='sound'){toggleSound();return;}if(b.dataset.jump!==undefined){start(b.dataset.kind,Number(b.dataset.jump));return;}if(game?.paused)return;if(b.dataset.intro){intro(b.dataset.intro);return;}if(a==='start'){start();return;}if(b.dataset.audio){say(b.dataset.audio);return;}if(a==='act'){act();return;}if(a==='demo'){showDemo();return;}if(a==='read'){if(game.phase==='choosing')say(game.q.questionAudio);else if(game.phase==='selected')say(game.q.audio);else playAnswer(game);return;}if(b.dataset.option){const g=game,ok=choose(g,b.dataset.option);if(ok===null)return;stopAudio();render();say(ok?content.words[b.dataset.option].audio:content.feedback['再試一試。']);return;}if(b.dataset.slot!==undefined&&game?.selected){place(game,game.selected,Number(b.dataset.slot));updateTrain();check();return;}if(b.dataset.token&&game?.phase==='assembling'){game.selected=b.dataset.token;say(content.words[game.selected].audio);updateTrain();return;}if(b.id==='word-bank'&&game?.selected){remove(game,game.selected);updateTrain();}});
// Multiple independent Pointer Events, one owner per card; no HTML5 drag dependency.
app.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-token]'),g=game;if(!b||b.disabled||g?.type!=='train'||g.paused||g.phase!=='assembling'||[...g.drags.values()].some(d=>d.id===b.dataset.token))return;const rect=b.getBoundingClientRect();g.drags.set(e.pointerId,{id:b.dataset.token,x:e.clientX,y:e.clientY,width:rect.width,height:rect.height,moved:false,ghost:null});app.setPointerCapture(e.pointerId);});
app.addEventListener('pointermove',e=>{const g=game,d=g?.drags.get(e.pointerId);if(!d||g.paused)return;if(!d.moved&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>8){d.moved=true;const original=$(`[data-token="${d.id}"]:not(:disabled)`);d.ghost=original.cloneNode(true);d.ghost.classList.add('drag-ghost');Object.assign(d.ghost.style,{width:d.width+'px',height:d.height+'px'});document.body.append(d.ghost);document.querySelectorAll(`[data-token="${d.id}"]`).forEach(el=>el.classList.add('dragging'));say(content.words[d.id].audio);}if(d.moved){e.preventDefault();Object.assign(d.ghost.style,{left:e.clientX-d.width/2+'px',top:e.clientY-d.height/2+'px'});document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');target?.classList.add('drop-target');}});
function endDrag(e,cancelled=false){const g=game,d=g?.drags.get(e.pointerId);if(!d)return;g.drags.delete(e.pointerId);d.ghost?.remove();if(app.hasPointerCapture(e.pointerId))app.releasePointerCapture(e.pointerId);if(d.moved||cancelled){e.preventDefault();if(!cancelled&&!g.paused){const hit=document.elementFromPoint(e.clientX,e.clientY),target=hit?.closest('[data-slot]');if(target)place(g,d.id,Number(target.dataset.slot));else if(hit?.closest('#word-bank'))remove(g,d.id);}updateTrain();if(!cancelled)check();}else{const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');if(g.selected&&target){place(g,g.selected,Number(target.dataset.slot));updateTrain();check();}else{g.selected=d.id;say(content.words[d.id].audio);updateTrain();}e.preventDefault();} }
app.addEventListener('pointerup',e=>endDrag(e));app.addEventListener('pointercancel',e=>endDrag(e,true));app.addEventListener('lostpointercapture',e=>endDrag(e,true));
app.addEventListener('dragstart',e=>{if(e.target.closest('[data-token]'))e.preventDefault();});
app.addEventListener('keydown',e=>{if(e.key==='Escape'&&game){e.preventDefault();togglePause();return;}const b=e.target.closest('[data-token],[data-slot]'),g=game;if(!b||g?.type!=='train'||g.paused||g.phase!=='assembling')return;if(['Delete','Backspace'].includes(e.key)&&b.dataset.token){e.preventDefault();remove(g,b.dataset.token);updateTrain();return;}if(!['Enter',' '].includes(e.key))return;e.preventDefault();if(b.dataset.slot!==undefined&&g.selected){place(g,g.selected,Number(b.dataset.slot));updateTrain();check();}else if(b.dataset.token){g.selected=b.dataset.token;say(content.words[g.selected].audio);updateTrain();}});
$('#app').addEventListener('click',e=>{if(e.target.id==='word-bank'&&game?.selected&&!game.paused){remove(game,game.selected);updateTrain();}});
window.addEventListener('popstate',home);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!game.paused)togglePause();});
function setAtlasFrame(el,frame,selector){el.dataset.frame=frame;el.querySelector(selector)?.setAttribute('viewBox',`${frame%4*400} ${Math.floor(frame/4)*300} 400 300`);}
function animate(now){const delta=now-lastFrame;lastFrame=now;const g=game;if(g&&!g.paused){g.clock.tick(delta);if(game===g){if(g.demo&&g.clock.position>=g.demo){g.demo=0;app.classList.remove('show-demo');}if(g.startedAt!==null){const elapsed=g.clock.position-g.startedAt,frame=Math.min(15,Math.floor(elapsed/2800*16));if(kind==='life'){document.querySelectorAll('.relation-cell .scene').forEach(el=>setAtlasFrame(el,el.closest('[data-side]').dataset.side==='left'?Math.min(frame,g.q.conditionFrame):frame,'.scene-window'));}else{document.querySelectorAll('[data-engine]').forEach(el=>setAtlasFrame(el,frame,'.engine-window'));document.querySelectorAll('.car-window').forEach(el=>{const [x,y,r,b]=TRAIN_CARRIAGE_ART.frames[frame].bounds,w=r-x,h=b-y;for(const [a,v]of Object.entries({x:(258-w)/2,y:270-h,width:w,height:h,viewBox:`${x} ${y} ${w} ${h}`}))el.setAttribute(a,v);});const rake=$('#rake');if(rake)rake.style.transform=`translateX(${Math.pow(Math.min(1,elapsed/2800),2)*140}vw)`;}}}}requestAnimationFrame(animate);}
requestAnimationFrame(animate);
const route=location.hash.slice(1);if(route.startsWith('review-')&&titles[route.slice(7)]){kind=route.slice(7);review();}else if(titles[route.replace('intro-','')])intro(route.replace('intro-',''));else home();
